/* Enforce strict hidden rule per constraints */
[hidden] {
  display: none !important;
}

:root {
  --color-bg: #1f271b;
  --color-card: #2d3a27;
  --color-card-border: #415338;
  --color-text: #e8f5e9;
  --color-text-muted: #a5d6a7;
  --color-accent: #4caf50;
  --color-accent-hover: #66bb6a;
  --color-accent-active: #388e3c;
  --color-warning: #e57373;
  --color-track: #151d13;
  --focus-ring: #81c784;
  --font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: var(--color-bg);
  font-family: var(--font-family);
  font-size: 16px;
  color: var(--color-text);
  padding: 1.5rem 1rem;
}

.app-container {
  width: 100%;
  max-width: 400px;
  min-width: 320px;
  display: flex;
  justify-content: center;
}

.card {
  width: 100%;
  background-color: var(--color-card);
  border: 2px solid var(--color-card-border);
  border-radius: 12px;
  padding: 1.75rem;
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.card-header {
  text-align: center;
}

.card-header h1 {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--color-text);
  letter-spacing: -0.02em;
}

.subtitle {
  font-size: 0.95rem;
  color: var(--color-text-muted);
  margin-top: 0.25rem;
}

.canvas-wrapper {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background-color: var(--color-track);
  border: 2px solid var(--color-card-border);
  border-radius: 8px;
  padding: 1rem;
  position: relative;
}

#plant-canvas {
  image-rendering: pixelated;
  image-rendering: crisp-edges;
  width: 128px;
  height: 128px;
}

.status-badge {
  margin-top: 0.75rem;
  font-size: 0.95rem;
  font-weight: 600;
  padding: 0.25rem 0.75rem;
  border-radius: 999px;
  background-color: var(--color-card-border);
  color: var(--color-text-muted);
}

.status-badge.wilted {
  background-color: rgba(229, 115, 115, 0.2);
  color: var(--color-warning);
  border: 1px solid var(--color-warning);
}

.meter-section {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.meter-header {
  display: flex;
  justify-content: space-between;
  font-size: 0.95rem;
  color: var(--color-text-muted);
  font-weight: 500;
}

.progress-track {
  height: 14px;
  background-color: var(--color-track);
  border: 1px solid var(--color-card-border);
  border-radius: 7px;
  overflow: hidden;
  position: relative;
}

.progress-fill {
  height: 100%;
  background-color: var(--color-accent);
  transition: width 0.15s linear, background-color 0.3s ease;
}

.progress-fill.wilted {
  background-color: var(--color-warning);
}

.controls {
  display: flex;
  justify-content: center;
}

.btn-water {
  width: 100%;
  font-family: inherit;
  font-size: 1.1rem;
  font-weight: 600;
  padding: 0.85rem 1.25rem;
  background-color: var(--color-accent);
  color: #0e1e0f;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background-color 0.15s ease, transform 0.08s ease;
  outline: none;
}

.btn-water:hover {
  background-color: var(--color-accent-hover);
}

.btn-water:active {
  background-color: var(--color-accent-active);
  transform: scale(0.98);
}

.btn-water:focus-visible {
  outline: 3px solid var(--focus-ring);
  outline-offset: 3px;
}

.stats-footer {
  text-align: center;
  border-top: 1px solid var(--color-card-border);
  padding-top: 1rem;
}

.water-counter-text {
  font-size: 1rem;
  color: var(--color-text-muted);
}

.water-counter-text strong {
  color: var(--color-text);
  font-size: 1.15rem;
}

document.addEventListener('DOMContentLoaded', () => {
  const TOTAL_DURATION_MS = 2 * 60 * 1000; // 120,000 ms (2 minutes)
  const WILT_THRESHOLD_PERCENT = 30;

  // State
  let moisture = 100; // Percentage: 0 to 100
  let waterCount = 0;
  let lastTimestamp = performance.now();

  // Elements
  const canvas = document.getElementById('plant-canvas');
  const ctx = canvas.getContext('2d');
  const moistureFill = document.getElementById('moisture-fill');
  const moisturePercent = document.getElementById('moisture-percent');
  const moistureBarTrack = document.getElementById('moisture-bar-track');
  const waterBtn = document.getElementById('water-btn');
  const waterCountElem = document.getElementById('water-count');
  const thirstyText = document.getElementById('thirsty-text');
  const healthyText = document.getElementById('healthy-text');
  const statusBadge = document.getElementById('status-badge');

  // Pixel Art Palette
  const PALETTE = {
    pot: '#8d5524',
    potRim: '#a66a38',
    soil: '#3e2723',
    stem: '#388e3c',
    leafHealthy: '#66bb6a',
    leafHealthyLight: '#81c784',
    leafWilted: '#9e9d24',
    leafWiltedDark: '#556b2f',
    eye: '#1b1b1b'
  };

  function drawPixel(x, y, color, size = 4) {
    ctx.fillStyle = color;
    ctx.fillRect(x * size, y * size, size, size);
  }

  function renderPlant(isWilted) {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const leafMain = isWilted ? PALETTE.leafWilted : PALETTE.leafHealthy;
    const leafShade = isWilted ? PALETTE.leafWiltedDark : PALETTE.leafHealthyLight;
    const stemColor = isWilted ? PALETTE.leafWiltedDark : PALETTE.stem;

    // 32x32 Grid inside 128x128 canvas (size = 4)
    // Pot drawing
    // Rim: x: 10 to 21, y: 22 to 23
    for (let x = 10; x <= 21; x++) {
      drawPixel(x, 22, PALETTE.potRim);
      drawPixel(x, 23, PALETTE.pot);
    }
    // Pot body
    for (let y = 24; y <= 29; y++) {
      const indent = Math.floor((y - 23) / 3);
      for (let x = 11 + indent; x <= 20 - indent; x++) {
        drawPixel(x, y, PALETTE.pot);
      }
    }
    // Soil
    for (let x = 12; x <= 19; x++) {
      drawPixel(x, 21, PALETTE.soil);
    }

    // Plant stem & foliage
    if (!isWilted) {
      // Healthy upright stem
      for (let y = 14; y <= 20; y++) {
        drawPixel(15, y, stemColor);
        drawPixel(16, y, stemColor);
      }

      // Left leaf
      drawPixel(12, 14, leafShade);
      drawPixel(13, 14, leafMain);
      drawPixel(14, 15, leafMain);
      drawPixel(11, 15, leafMain);
      drawPixel(12, 16, leafMain);
      drawPixel(13, 16, leafShade);
      drawPixel(14, 16, stemColor);

      // Right leaf
      drawPixel(18, 13, leafShade);
      drawPixel(19, 13, leafMain);
      drawPixel(20, 14, leafMain);
      drawPixel(17, 14, stemColor);
      drawPixel(18, 15, leafMain);
      drawPixel(19, 15, leafMain);

      // Center crown sprout
      for (let y = 8; y <= 13; y++) {
        for (let x = 14; x <= 17; x++) {
          const color = (x === 14 || y === 8) ? leafShade : leafMain;
          drawPixel(x, y, color);
        }
      }

      // Happy little face
      drawPixel(15, 11, PALETTE.eye);
      drawPixel(17, 11, PALETTE.eye);
      drawPixel(16, 12, PALETTE.eye);
    } else {
      // Wilted droopy stem
      drawPixel(15, 20, stemColor);
      drawPixel(16, 20, stemColor);
      drawPixel(14, 19, stemColor);
      drawPixel(15, 19, stemColor);
      drawPixel(13, 18, stemColor);
      drawPixel(14, 18, stemColor);
      drawPixel(12, 17, stemColor);
      drawPixel(13, 17, stemColor);

      // Wilted left leaf (drooping toward pot)
      drawPixel(9, 21, leafShade);
      drawPixel(10, 20, leafMain);
      drawPixel(11, 19, leafMain);
      drawPixel(10, 21, leafMain);

      // Wilted center/right leaf (drooping down)
      drawPixel(11, 15, leafShade);
      drawPixel(12, 15, leafMain);
      drawPixel(11, 16, leafMain);
      drawPixel(10, 17, leafMain);
      drawPixel(10, 18, leafShade);

      // Drooped head
      for (let y = 14; y <= 18; y++) {
        for (let x = 14; x <= 17; x++) {
          const color = (y >= 17) ? leafShade : leafMain;
          drawPixel(x, y, color);
        }
      }

      // Sad face
      drawPixel(14, 15, PALETTE.eye);
      drawPixel(16, 15, PALETTE.eye);
      drawPixel(15, 17, PALETTE.eye);
    }
  }

  function updateUI() {
    const isWilted = moisture < WILT_THRESHOLD_PERCENT;
    const clampedMoisture = Math.max(0, Math.min(100, moisture));

    // Moisture bar update
    moistureFill.style.width = clampedMoisture.toFixed(1) + '%';
    moisturePercent.textContent = Math.round(clampedMoisture) + '%';
    moistureBarTrack.setAttribute('aria-valuenow', Math.round(clampedMoisture));

    if (isWilted) {
      moistureFill.classList.add('wilted');
      statusBadge.classList.add('wilted');
      thirstyText.removeAttribute('hidden');
      healthyText.setAttribute('hidden', '');
    } else {
      moistureFill.classList.remove('wilted');
      statusBadge.classList.remove('wilted');
      healthyText.removeAttribute('hidden');
      thirstyText.setAttribute('hidden', '');
    }

    renderPlant(isWilted);
  }

  function gameLoop(currentTimestamp) {
    const delta = currentTimestamp - lastTimestamp;
    lastTimestamp = currentTimestamp;

    // Moisture drains over 2 minutes (120,000ms)
    const drainRate = 100 / TOTAL_DURATION_MS; // % per ms
    if (moisture > 0) {
      moisture = Math.max(0, moisture - (drainRate * delta));
      updateUI();
    }

    requestAnimationFrame(gameLoop);
  }

  function waterPlant() {
    moisture = 100;
    waterCount += 1;
    waterCountElem.textContent = waterCount;
    updateUI();
  }

  waterBtn.addEventListener('click', waterPlant);

  // Initial render and loop kick-off
  updateUI();
  requestAnimationFrame((ts) => {
    lastTimestamp = ts;
    gameLoop(ts);
  });
});
